#include <iostream>
#include <string>
#include <iomanip>

class BMI {
public:
    BMI(const std::string& newName, int newAge, double newWeightPounds, double newHeightInches)
        : name(newName), age(newAge), weight(newWeightPounds), height(newHeightInches) {}

    BMI(const std::string& newName, double newWeightPounds, double newHeightInches)
        : BMI(newName, 20, newWeightPounds, newHeightInches) {} // C++11 delegating constructor

    double getBMI() const {
        constexpr double KILOGRAMS_PER_POUND = 0.45359237;
        constexpr double METERS_PER_INCH = 0.0254;
        double heightMeters = height * METERS_PER_INCH;
        return (weight * KILOGRAMS_PER_POUND) / (heightMeters * heightMeters);
    }

    std::string getStatus() const {
        double bmi = getBMI();
        if (bmi < 18.5) return "Underweight";
        if (bmi < 25.0) return "Normal";
        if (bmi < 30.0) return "Overweight";
        return "Obese";
    }

    std::string getName() const { return name; }
    int getAge() const { return age; }
    double getWeight() const { return weight; }
    double getHeight() const { return height; }

private:
    std::string name;
    int age{20};
    double weight{0.0};
    double height{0.0};
};

int main() {
    std::string candidateName = "John Doe";
    BMI person1(candidateName, 18, 145.0, 70.0);

    // Verify value copy semantics
    candidateName[0] = 'P';
    std::cout << "Candidate variable: " << candidateName << "\n";
    std::cout << "BMI Object Name: " << person1.getName() << "\n";
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "BMI: " << person1.getBMI() << " Status: " << person1.getStatus() << "\n";

    BMI person2("Susan King", 215.0, 70.0);
    std::cout << "BMI Object Name: " << person2.getName() << "\n";
    std::cout << "BMI: " << person2.getBMI() << " Status: " << person2.getStatus() << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <memory>

// Composition: Name is exclusively owned by Student
class Name {
public:
    Name(const std::string& first, const std::string& last) 
        : firstName(first), lastName(last) {}
    std::string getFullName() const { return firstName + " " + lastName; }
private:
    std::string firstName;
    std::string lastName;
};

// Aggregation: Address can exist independently and be shared
class Address {
public:
    Address(const std::string& street, const std::string& city)
        : streetName(street), cityName(city) {}
    std::string getAddress() const { return streetName + ", " + cityName; }
private:
    std::string streetName;
    std::string cityName;
};

class Student {
public:
    // Composition for Name (passed by value to construct internal member)
    // Aggregation for Address (shared pointer to external instance)
    Student(const std::string& first, const std::string& last, std::shared_ptr<Address> sharedAddr)
        : name(first, last), address(sharedAddr) {}

    void display() const {
        std::cout << "Student: " << name.getFullName() 
                  << " | Address: " << (address ? address->getAddress() : "None") << "\n";
    }

private:
    Name name;                         // Composition (filled diamond in UML)
    std::shared_ptr<Address> address;  // Aggregation (empty diamond in UML, shared)
};

int main() {
    // Shared address instance (Multiplicity 1..3 students sharing 1 address)
    auto sharedCampusDorm = std::make_shared<Address>("100 University Ave", "Tech City");

    Student student1("Alice", "Smith", sharedCampusDorm);
    Student student2("Bob", "Jones", sharedCampusDorm);

    student1.display();
    student2.display();

    std::cout << "Address sharing count: " << sharedCampusDorm.use_count() << "\n";
    return 0;
}
